<style>
:root{--bg:#050b13;--panel:#0b1522;--panel2:#0e1c2d;--line:#20364d;--text:#edf6ff;--muted:#91a7bd;--green:#28e0a1;--red:#ff5f73;--yellow:#ffd166;--blue:#55a9ff;--dark:#02060b}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#123354 0,transparent 34%),var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}button,input,select{font:inherit}.wrap{max-width:1240px;margin:auto;padding:20px}.nav{display:flex;justify-content:space-between;align-items:center;padding:8px 0 22px;gap:15px}.brand{font-weight:900;font-size:21px}.brand span{color:var(--green)}.status{font-size:11px;color:#9de8cb;border:1px solid #285846;padding:8px 12px;border-radius:999px;background:#081d18}.card{background:linear-gradient(180deg,#0e1c2d,#08121e);border:1px solid var(--line);border-radius:20px;padding:22px;box-shadow:0 16px 45px #0006}.hero{display:grid;grid-template-columns:1.15fr .85fr;gap:18px}.eyebrow{color:var(--green);font-size:11px;font-weight:900;letter-spacing:.15em;text-transform:uppercase}.hero h1{font-size:clamp(30px,5vw,55px);line-height:1.02;margin:12px 0}.hero p{color:var(--muted);line-height:1.65}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}label{font-size:11px;color:var(--muted);display:block;margin-bottom:6px}select{width:100%;background:#06101b;border:1px solid var(--line);color:var(--text);padding:12px;border-radius:11px}.drop{margin-top:13px;border:1px dashed #39617f;border-radius:15px;padding:18px;text-align:center;background:#07121e}.drop.drag{border-color:var(--green)}.drop input{width:100%;margin-top:10px}.preview{display:none;margin:14px auto 0;max-height:280px;max-width:100%;object-fit:contain;border-radius:12px}.btn{width:100%;margin-top:14px;border:0;border-radius:12px;padding:14px;font-weight:900;cursor:pointer;background:linear-gradient(90deg,var(--green),#66edc0);color:#03120e}.btn:disabled{opacity:.55;cursor:wait}.checks{display:grid;gap:10px;margin-top:16px}.check{display:flex;gap:9px;color:#b7c9dc;font-size:13px;line-height:1.45}.dot{width:8px;height:8px;border-radius:50%;background:var(--green);margin-top:5px;flex:0 0 auto}.result{display:none;margin-top:18px}.topline{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap}.pill{display:inline-block;border:1px solid #31516e;padding:6px 9px;border-radius:999px;color:#b8d1e8;font-size:11px;margin:3px}.direction{font-size:22px;font-weight:950;padding:10px 14px;border-radius:13px;border:1px solid var(--line)}.bull{color:var(--green);background:#06251c}.bear{color:var(--red);background:#2a0a12}.neutral{color:var(--yellow);background:#2a2106}.chartbox{margin-top:17px;border:1px solid #29435c;border-radius:16px;background:#02070d;overflow:hidden}.chartstage{position:relative;width:100%;line-height:0}.chartstage canvas{display:block;width:100%;height:auto}.legend{display:flex;gap:7px;flex-wrap:wrap;padding:10px;border-top:1px solid #20364d;background:#07111b}.legend span{font-size:10px;border:1px solid #2b4055;padding:5px 7px;border-radius:999px;color:#afc1d3}.grid2{display:grid;grid-template-columns:1.25fr .75fr;gap:16px;margin-top:16px}.story,.tutorial,.scenario,.conclusion{border:1px solid var(--line);border-radius:15px;padding:17px;background:#091521}.story h3,.tutorial h3,.scenario h3,.conclusion h3{margin:0 0 11px}.story ol{margin:0;padding-left:22px}.story li{margin:8px 0;color:#c9d8e7;line-height:1.5}.tutorialItem{padding:10px 0;border-bottom:1px solid #1b2d40}.tutorialItem:last-child{border-bottom:0}.tutorialItem b{color:#fff}.tutorialItem div{color:#9fb2c5;font-size:13px;line-height:1.5;margin-top:4px}.scenarioGrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.scenario{border-color:#2d4d68}.scenario.bullish{border-color:#23684f}.scenario.bearish{border-color:#6c2b37}.scenario p{color:#b8c9d9;font-size:13px;line-height:1.55}.key{display:flex;gap:8px;align-items:flex-start;margin:8px 0;color:#c5d5e5;font-size:13px}.key:before{content:'•';color:var(--yellow);font-size:20px;line-height:12px}.mini{color:#8fa5bb;font-size:11px;line-height:1.5}.footer{padding:24px 0;color:#71869c;font-size:11px;text-align:center}@media(max-width:850px){.hero,.grid2,.scenarioGrid{grid-template-columns:1fr}.formgrid{grid-template-columns:1fr}.wrap{padding:13px}.card{padding:17px}}
</style>
</head>
<body>
<div class="wrap">
<header class="nav"><div class="brand">PRIMONIZER <span>FOREX AI</span></div><div class="status">● VISUAL MARKET TUTOR</div></header>
<section class="hero">
<div class="card"><div class="eyebrow">Visual market intelligence</div><h1>See the market story, not just a text report.</h1><p>Upload a candlestick screenshot. The engine reads the largest visible chart area, marks important candles and zones, then draws a directional scenario directly on the chart.</p>
<form id="form" enctype="multipart/form-data"><div class="formgrid"><div><label>SYMBOL</label><select name="symbol"><option>XAUUSD</option><option>EURUSD</option><option>GBPUSD</option><option>USDJPY</option><option>BTCUSD</option><option>V75</option><option>OTHER</option></select></div><div><label>TIMEFRAME</label><select name="timeframe"><option>M1</option><option>M5</option><option>M15</option><option>M30</option><option>H1</option><option>H4</option><option>D1</option><option>UNKNOWN</option></select></div></div><div class="drop" id="drop"><strong>Drop candlestick screenshot here</strong><div style="color:#7890a7;font-size:12px;margin:7px 0">PNG, JPG, WEBP — clear chart screenshots work best</div><input id="image" type="file" name="chart" accept="image/png,image/jpeg,image/webp" required><img id="preview" class="preview" alt="Chart preview"></div><button class="btn" id="submit">ANALYZE MARKET VISUALLY</button></form></div>
<div class="card"><div class="eyebrow">Tutor mode</div><h3>What the analyzer teaches</h3><div class="checks"><div class="check"><span class="dot"></span>Reads the full visible structure before focusing on current price.</div><div class="check"><span class="dot"></span>Marks HH, HL, LH, LL, BOS and CHoCH on the actual chart.</div><div class="check"><span class="dot"></span>Highlights liquidity, sweeps, OB and FVG candidates.</div><div class="check"><span class="dot"></span>Shows a bullish and bearish scenario with invalidation.</div><div class="check"><span class="dot"></span>Draws the primary UP, DOWN or WAIT path visually.</div><div class="check"><span class="dot"></span>Explains the market story in short tutorial steps.</div></div><p class="mini" style="margin-top:18px">Directional output is a chart-based scenario, not a guaranteed next-candle prediction or profit promise.</p></div>
</section>
<section class="result" id="result"><div class="card"><div class="topline"><div><span class="pill" id="symbolPill"></span><span class="pill" id="tfPill"></span><span class="pill">VISUAL AI</span></div><div class="direction neutral" id="direction">WAIT</div></div><h2 id="headline" style="margin:14px 0 6px"></h2><div class="mini" id="state"></div><div class="chartbox"><div class="chartstage"><canvas id="chartCanvas"></canvas></div><div class="legend"><span>● CURRENT</span><span>■ OB</span><span>■ FVG</span><span>◆ LIQUIDITY</span><span>↗ BOS/CHoCH</span><span>━━ SCENARIO PATH</span></div></div></div>
<div class="grid2"><div class="story"><h3>Market story</h3><ol id="story"></ol></div><div class="tutorial"><h3>Tutorial view</h3><div id="tutorial"></div></div></div>
<div class="scenarioGrid"><div class="scenario bullish"><h3>🟢 Bullish scenario</h3><p id="bullCase"></p></div><div class="scenario bearish"><h3>🔴 Bearish scenario</h3><p id="bearCase"></p></div></div>
<div class="grid2"><div class="conclusion"><h3>What to watch</h3><div class="key" id="watch"></div><div class="key" id="invalid"></div><div id="levels"></div></div><div class="conclusion"><h3>Directional conclusion</h3><div id="diagram" style="font-size:15px;line-height:1.7"></div><p class="mini" id="risk"></p></div></div></section>
<div class="footer">Primonizer Forex AI • Visual research and trader education</div>
</div>
<script>
const image=document.getElementById('image'),preview=document.getElementById('preview'),drop=document.getElementById('drop'),canvas=document.getElementById('chartCanvas'),ctx=canvas.getContext('2d');let lastImage=null,lastAnalysis=null;
image.addEventListener('change',()=>{const f=image.files[0];if(f){preview.src=URL.createObjectURL(f);preview.style.display='block'}});
['dragenter','dragover'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>{if(e.dataTransfer.files.length){image.files=e.dataTransfer.files;image.dispatchEvent(new Event('change'))}});
function clamp(v,a=0,b=1){return Math.max(a,Math.min(b,Number(v)||0))}
function colorFor(type){if(type==='OB_BULL'||type==='SUPPORT'||type==='HL')return '#28e0a1';if(type==='OB_BEAR'||type==='RESISTANCE'||type==='LH')return '#ff5f73';if(type==='FVG')return '#55a9ff';if(type==='LIQUIDITY'||type==='SWEEP'||type==='PREMIUM'||type==='DISCOUNT')return '#ffd166';if(type==='CURRENT')return '#ffffff';return '#b7c8d9'}
function drawChart(img,a){const maxW=1180,scale=Math.min(1,maxW/img.naturalWidth),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));canvas.width=w;canvas.height=h;ctx.clearRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);ctx.save();ctx.lineWidth=Math.max(2,w/550);ctx.font='700 '+Math.max(10,w/85)+'px Segoe UI,Arial';
(a.annotations||[]).forEach(o=>{const x=clamp(o.x)*w,y=clamp(o.y)*h,x2=o.x2==null?x:clamp(o.x2)*w,y2=o.y2==null?y:clamp(o.y2)*h,c=colorFor(o.type);ctx.strokeStyle=c;ctx.fillStyle=c;ctx.globalAlpha=.78;if(o.x2!=null&&o.y2!=null){ctx.fillStyle=c+'28';ctx.strokeRect(Math.min(x,x2),Math.min(y,y2),Math.abs(x2-x),Math.abs(y2-y));ctx.fillRect(Math.min(x,x2),Math.min(y,y2),Math.abs(x2-x),Math.abs(y2-y))}else{ctx.beginPath();ctx.arc(x,y,Math.max(5,w/130),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;let tx=Math.min(w-130,Math.max(5,x+8)),ty=Math.max(15,y-8);ctx.fillText(o.label||o.type,tx,ty)});
const path=(a.path||[]).filter(p=>p&&p.direction);if(path.length>1){ctx.lineWidth=Math.max(3,w/360);ctx.setLineDash([10,7]);ctx.strokeStyle=a.direction==='BEARISH'?'#ff5f73':a.direction==='BULLISH'?'#28e0a1':'#ffd166';ctx.beginPath();path.forEach((p,i)=>{const x=clamp(p.x)*w,y=clamp(p.y)*h;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke();ctx.setLineDash([]);path.forEach(p=>{const x=clamp(p.x)*w,y=clamp(p.y)*h;ctx.beginPath();ctx.arc(x,y,Math.max(4,w/170),0,Math.PI*2);ctx.fill();ctx.fillText(p.label||'',Math.min(w-100,x+7),Math.max(13,y-7))})}ctx.restore()}
function render(data){const a=data.analysis||{};lastAnalysis=a;document.getElementById('result').style.display='block';document.getElementById('symbolPill').textContent=data.symbol||'Chart';document.getElementById('tfPill').textContent=data.timeframe||'Unknown';const d=document.getElementById('direction');d.textContent=(a.direction||'NEUTRAL')+' • '+(a.next_move||'WAIT');d.className='direction '+((a.direction||'NEUTRAL').toLowerCase()==='bullish'?'bull':(a.direction||'').toLowerCase()==='bearish'?'bear':'neutral');document.getElementById('headline').textContent=a.headline||'Visual analysis complete';document.getElementById('state').textContent=(a.current_state||'')+' Evidence confidence: '+(a.confidence??0)+'%.';document.getElementById('bullCase').textContent=a.bullish_case||'No bullish scenario returned.';document.getElementById('bearCase').textContent=a.bearish_case||'No bearish scenario returned.';document.getElementById('watch').textContent=a.watch_zone||'Watch the marked zones and current-price reaction.';document.getElementById('invalid').textContent='Invalidation: '+(a.invalidation||'Not clearly defined from the screenshot.');document.getElementById('risk').textContent=a.risk_note||'Use independent risk management.';
const story=document.getElementById('story');story.innerHTML='';(a.market_story||[]).forEach(x=>{const li=document.createElement('li');li.textContent=x;story.appendChild(li)});const tut=document.getElementById('tutorial');tut.innerHTML='';(a.tutorial||[]).forEach(x=>{const div=document.createElement('div');div.className='tutorialItem';div.innerHTML='<b>'+escapeHtml(x.title||'Step')+'</b><div>'+escapeHtml(x.text||'')+'</div>';tut.appendChild(div)});const lev=document.getElementById('levels');(a.key_levels||[]).forEach(x=>{const p=document.createElement('div');p.className='key';p.textContent=x;lev.appendChild(p)});const arrow=a.next_move==='UP'?'🟢  CURRENT  →  ↑  POSSIBLE UP  →  TARGET':a.next_move==='DOWN'?'🔴  CURRENT  →  ↓  POSSIBLE DOWN  →  TARGET':'🟡  CURRENT  →  WAIT FOR CONFIRMATION';document.getElementById('diagram').textContent=arrow+'\n\nPrimary bias: '+(a.direction||'NEUTRAL')+'\nInvalidation: '+(a.invalidation||'not defined');
const img=new Image();img.onload=()=>drawChart(img,a);img.src=lastImage;document.getElementById('result').scrollIntoView({behavior:'smooth'})}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
document.getElementById('form').addEventListener('submit',async e=>{e.preventDefault();const f=image.files[0];if(!f)return;lastImage=URL.createObjectURL(f);const btn=document.getElementById('submit');btn.disabled=true;btn.textContent='READING FULL CHART…';try{const r=await fetch('analyze.php',{method:'POST',body:new FormData(e.target)});const data=await r.json();if(!r.ok||data.error)throw new Error(data.error||'Analysis failed');render(data)}catch(err){document.getElementById('result').style.display='block';document.getElementById('headline').textContent='Analysis error';document.getElementById('state').textContent=err.message}finally{btn.disabled=false;btn.textContent='ANALYZE MARKET VISUALLY'}});
</script>
</body></html>
